const PARSERS = {'manife.st': 'manifest', 'live.handelsblatt.com': 'handelsblatt', 'www.bme.de': 'bme', 'financeaccountingtech.com': 'fate', 'nrfbigshow.nrf.com': 'nrf', 'events.iofm.com': 'iofm', 'radiance.highradius.com':'radiance', 'cfoevents.financealliance.io':'acara'};
const base = $input.all().map(i => {
  const e = i.json;
  const m = String(e.speakers_url).match(/^(https?:\/\/([^\/]+))(\/[^\s]*)?$/);
  const full = m[3] || '/';
  const path = full.split('#')[0].split('?')[0];
  return {json: {slug: e.slug, name: e.name, market: e.market, url: e.speakers_url, origin: m[1], path: path, parser: PARSERS[m[2]] || null}};
});
const EXTRA = [
  {slug: 'handelsblatt-cpo-summit-2027', name: 'Handelsblatt CPO-Summit', market: 'DE', url: 'https://live.handelsblatt.com/event/handelsblatt-cpo-summit/cpo-summit-2025/referentinnen/', kind: 'speaker (2025 edition)'}
];
const extras = EXTRA.map(e => { const m = e.url.match(/^(https:\/\/([^\/]+))(\/[^\s]*)$/); return {json: {slug: e.slug, name: e.name, market: e.market, url: e.url, origin: m[1], path: m[3].split('?')[0].split('#')[0], parser: PARSERS[m[2]] || null, kind: e.kind}}; });
return base.concat(extras);

const plan = $('Plan').all();
return $input.all().map((r, i) => {
  const p = plan[i].json;
  const txt = String(r.json.data || '');
  let allowed = true, reason = 'ok';
  if (!p.parser) {
    allowed = false; reason = 'no_parser_for_' + p.origin;
  } else {
    const lines = txt.split(/\r?\n/).map(l => l.replace(/#.*/, '').trim()).filter(Boolean);
    let applies = false;
    const rules = [];
    for (const l of lines) {
      const m = l.match(/^([a-z-]+)\s*:\s*(.*)$/i);
      if (!m) continue;
      const k = m[1].toLowerCase(), v = m[2].trim();
      if (k === 'user-agent') applies = v === '*';
      else if (applies && (k === 'disallow' || k === 'allow')) rules.push([k, v]);
    }
    let best = null;
    for (const [k, v] of rules) {
      if (v && p.path.startsWith(v) && (!best || v.length > best[1].length)) best = [k, v];
    }
    if (best && best[0] === 'disallow') { allowed = false; reason = 'robots_disallow ' + best[1]; }
  }
  return {json: {...p, node: 'Gate', allowed, reason}};
});

const html = String($json.data || '');
const src = $('Gate').item.json;
const dec = s => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d))
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const cleanName = n => dec(n).replace(/^((prof\.?|dr\.?(-[a-z]+\.?)?|dipl\.-[a-z]+\.?|mag\.?|h\.c\.?)\s+)+/i, '').replace(/,?\s*(MBA|PhD|M\.Sc\.|MSc)\.?$/i, '').trim();

const people = [];
if (src.parser === 'radiance') {
  const re = /alt="([^"]*?)\s*logo"[^>]*>\s*<\/noscript>\s*<div class="speaker-container">\s*<p class="session-speaker">([\s\S]*?)<\/p>\s*<p class="speaker-desig">([\s\S]*?)<\/p>/gi;
  for (const m of html.matchAll(re)) people.push({name: cleanName(m[2]), title: dec(m[3]), company: dec(m[1]).replace(/\s+(Incorporated|Inc\.?|Global)$/i, '')});
}
if (src.parser === 'acara') {
  const re = /"position":"([^"]*)","firstName":"([^"]*)","lastName":"([^"]*)"[\s\S]*?"speakerCompany":\{"companieId":"[^"]*","name":"([^"]*)"/g;
  for (const m of html.matchAll(re)) people.push({name: cleanName(m[2] + ' ' + m[3]), title: dec(m[1]), company: dec(m[4])});
}
if (src.parser === 'manifest') {
  const re = /<p class="speaker-name">([\s\S]*?)<\/p>\s*<p class="speaker-title">([\s\S]*?)<\/p>\s*<p class="speaker-company">([\s\S]*?)<\/p>/g;
  for (const m of html.matchAll(re)) people.push({name: cleanName(m[1]), title: dec(m[2]), company: dec(m[3])});
} else if (src.parser === 'handelsblatt') {
  const re = /<span class="ce-speaker__name">([\s\S]*?)<\/span>\s*<span class="ce-speaker__role">([\s\S]*?)<\/span>/g;
  for (const m of html.matchAll(re)) {
    const role = dec(m[2]);
    const k = Math.max(role.lastIndexOf(' – '), role.lastIndexOf(' - '));
    people.push({name: cleanName(m[1]), title: k > 0 ? role.slice(0, k) : role, company: k > 0 ? role.slice(k + 3) : ''});
  }
} else if (src.parser === 'bme') {
  const body = html.slice(Math.max(0, html.indexOf('<body')));
  const re = /<p class="mt-2 prose-sm line-clamp-2[^"]*">([\s\S]*?)<\/p>/g;
  for (const m of body.matchAll(re)) {
    const parts = dec(m[1]).split(',').map(s => s.trim()).filter(Boolean);
    if (parts.length >= 3) people.push({name: cleanName(parts[0]), title: [parts[1]].concat(parts.slice(3)).join(', '), company: parts[2]});
  }
} else if (src.parser === 'fate') {
  const re = /tec-session-speaker-name">\s*([\s\S]*?)\s*<\/div>\s*<div class="tec-session-speaker-title-organization">\s*([\s\S]*?)\s*<\/div>/g;
  for (const m of html.matchAll(re)) {
    const parts = dec(m[2]).replace(/&rsquo;/g, "'").replace(/&[nm]dash;/g, '-').split(',').map(s => s.trim()).filter(Boolean);
    while (parts.length > 2 && /^(inc\.?|llc|ltd\.?|corp\.?|co\.?|gmbh|plc)$/i.test(parts[parts.length - 1])) { const last = parts.pop(); parts[parts.length - 1] += ', ' + last; }
    if (parts.length >= 2) people.push({name: cleanName(m[1]), title: parts.slice(0, -1).join(', '), company: parts[parts.length - 1]});
  }
} else if (src.parser === 'nrf') {
  const re = /SpeakersList_name__\w+">([\s\S]*?)<\/p>\s*<p>([\s\S]*?)<\/p>\s*<p class="SpeakersList_company__\w+">([\s\S]*?)<\/p>/g;
  for (const m of html.matchAll(re)) people.push({name: cleanName(m[1]), title: dec(m[2]).replace(/&rsquo;/g, "'"), company: dec(m[3]).replace(/&rsquo;/g, "'")});
}

 else if (src.parser === 'iofm') {
  const re = /person__info--name">\s*<p>\s*(?:<a [^>]*>)?\s*([\s\S]*?)\s*(?:<\/a>)?\s*<\/p>\s*<\/div>\s*<div class="person__info--company">\s*<p>([\s\S]*?)<\/p>\s*<\/div>\s*<div class="person__info--title">\s*<p>([\s\S]*?)<\/p>/g;
  for (const m of html.matchAll(re)) people.push({name: cleanName(m[1]), title: dec(m[3]), company: dec(m[2])});
}
const FUNC = [
  ['procurement', /procure|purchas|sourcing|einkauf|einkäuf|einkaeuf|beschaffung|supplier|\bcpo\b|\bbuyers?\b|category manag|indirect|\bspend\b/i],
  ['supply chain', /supply\s*(chain|officer)|\bscm\b|logistic|lieferkett|fulfil|warehouse|demand|planning|transport|materials?\s+manag|inventory|trade compliance|global trade|customs/i],
  ['finance ops', /finance|financial|accounting|payable|receivable|controll|treasury|\bcfo\b|shared service|business services|\bgbs\b|order[- ]to[- ]cash|procure[- ]to[- ]pay|\bp2p\b|\bo2c\b|\bap\b|\bar\b|credit|collections|billing|invoic|order management|\bcash\b/i],
  ['operations or IT', /operations|process (manager|owner|excellence|improvement)|operating officer|information officer|\berp\b|\bsap\b|transformation|digital|\bcoo\b|\bcio\b/i]
];
const NONBUYER = /investor|venture|capital|angel|founder|professor|journalist|moderator|chefvolkswirt|economist|minister|politik|referent\b|\bhost\b|author|keynote/i;
const ACADEMIC = /universit|hochschule|fraunhofer|institut\b|akademie|academy/i;
const HIGH = /\b(chief|cpo|cfo|coo|ceo|cio|cto|president|vice president|vp|svp|evp|head|director|direktor\w*|vorstand\w*|leiter\w*|leitung|bereichsleit\w*|abteilungsleit\w*|geschäftsführ\w*|managing|einkaufsleiter\w*)\b/i;
const MID = /\b(manager|lead|senior|principal|process owner|teamleit\w*)\b/i;
const VENDOR = /\b(software|saas|ai|labs?|platform|cloud|analytics|robotics|technolog\w*|solutions?|consult\w*|advisory|startup|ventures?)\b/i;

const WEDGE = /accounts?\s*(payable|receivable)|\bap\b|\bar\b|invoic|billing|collections|credit|order[- ]to[- ]cash|procure[- ]to[- ]pay|\bp2p\b|\bo2c\b|order management|order fulfil|shared service|\bgbs\b|business services|purchasing|purchase|einkauf|einkäuf|procurement operations|buchhaltung|kreditoren|debitoren|rechnung|auftragsabwicklung|order processing/i;
const normCo = s => (s || '').toLowerCase().replace(/\b(gmbh|ag|se|inc|ltd|llc|plc|co|kg|corp|corporation|company|group|holding|limited)\b\.?/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
function funcOf(p) {
  if (NONBUYER.test(p.title) || ACADEMIC.test(p.company)) return null;
  for (const [label, re] of FUNC) if (re.test(p.title)) return label;
  return null;
}
// Fast-and-frugal tree. One cue per node, one exit per node, fixed order, no weighting.
// N1 buyer function -> X | N2 vendor -> X | N3 below manager -> C | N4 process-owner title -> A
// N5 senior with a second buyer from the same account at this event -> A | N6 technical evaluator without a champion -> C | rest -> B
function tree(p, acct) {
  const fn = funcOf(p);
  if (!fn) return {tier: 'X', drop: true, detail: {node: 'N1', path: 'N1 buyer function: none in title, so excluded'}};
  const seniority = HIGH.test(p.title) ? 'senior' : MID.test(p.title) ? 'manager' : 'below manager';
  const n = (acct[normCo(p.company)] || new Set()).size;
  const base = {function: fn, seniority, account_people: n};
  if (VENDOR.test(p.company)) return {tier: 'X', detail: {...base, vendor: true, node: 'N2', path: 'N1 function ' + fn + ' > N2 company looks like a vendor, so X'}};
  if (seniority === 'below manager') return {tier: 'C', detail: {...base, vendor: false, node: 'N3', role: 'influencer', path: 'N1 function ' + fn + ' > N2 not a vendor > N3 seniority below manager, so C'}};
  if (WEDGE.test(p.title)) return {tier: 'A', detail: {...base, vendor: false, node: 'N4', role: 'champion', path: 'N1 function ' + fn + ' > N2 not a vendor > N3 ' + seniority + ' > N4 title owns the invoice, payment, order or purchasing process, so A (champion)'}};
  if (seniority === 'senior' && n >= 2) return {tier: 'A', detail: {...base, vendor: false, node: 'N5', role: 'economic buyer', path: 'N1 function ' + fn + ' > N2 not a vendor > N3 senior > N4 no process-owner title > N5 ' + n + ' buyers from this account at the event, so A (economic buyer, account has a committee)'}};
  if (fn === 'operations or IT') return {tier: 'C', detail: {...base, vendor: false, node: 'N6', role: 'technical evaluator', path: 'N1 function operations or IT > N2 not a vendor > N3 ' + seniority + ' > N4 no process-owner title > N5 no second buyer from this account > N6 technical evaluator without a champion, so C'}};
  if (fn === 'supply chain' && seniority === 'manager') return {tier: 'C', detail: {...base, vendor: false, node: 'N6', role: 'influencer', path: 'N1 function supply chain > N2 not a vendor > N3 manager > N4 no process-owner title > N5 no second buyer > N6 supply chain manager, so C'}};
  return {tier: 'B', detail: {...base, vendor: false, node: seniority === 'senior' ? 'N7' : 'N8', role: seniority === 'senior' ? 'economic buyer' : 'influencer', path: 'N1 function ' + fn + ' > N2 not a vendor > N3 ' + seniority + ' > N4 no process-owner title > N5 no second buyer > N6 not a technical evaluator, so B'}};
}
const acct = {};
for (const p of people) { if (p.name && p.company && funcOf(p) && !VENDOR.test(p.company)) { const k = normCo(p.company); (acct[k] = acct[k] || new Set()).add(p.name.toLowerCase()); } }

const COMP_HOST = new Set(['radiance-2027']); // host sells overlapping order-to-cash software, speakers are mostly its customers
const seen = new Set();
const rows = [];
const tiers = {A: 0, B: 0, C: 0, X: 0};
let dropped = 0, noCompany = 0;
for (const p of people) {
  if (!p.name || !p.company) { noCompany++; continue; }
  const key = (p.name + '|' + p.company).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  const r = tree(p, acct);
  if (COMP_HOST.has(src.slug)) { if (r.tier === 'A') { r.tier = 'B'; r.detail = {...r.detail, competitor_host: true, node: 'N2b', path: r.detail.path + ' > N2b event host sells overlapping order-to-cash software, so the speaker is likely its customer, capped at B'}; } else { r.detail = {...r.detail, competitor_host: true}; } }
  if (r.drop) { dropped++; continue; }
  tiers[r.tier]++;
  rows.push({event_slug: src.slug, full_name: p.name, title: p.title, company: p.company, source_url: src.url,
    source_kind: src.kind || (src.parser === 'handelsblatt' ? 'speaker (2026 edition)' : 'speaker'), tier: r.tier, score_detail: r.detail});
}
const error = seen.size === 0 ? 'zero_people_parsed (page layout changed, blocked, or empty)' : (rows.length === 0 ? 'all_people_filtered_by_tree' : null);
return {json: {slug: src.slug, url: src.url, node: 'Parse', parser: src.parser, found: seen.size, dropped_by_tree: dropped, skipped_no_company: noCompany, tiers, error, rows}};
